              {movieIdx === 1 && <div className="relative mt-2"><div className="grid grid-cols-2 gap-3"><div><div className="flex justify-between text-sm font-black text-[#0F172A]"><span>🔵 {tr("Blue", "نیلا", "أزرق")}</span><span>80 ❤️</span></div><div className="hp-bar mt-1"><div className="hp-fill" style={{ width: `${movieStep >= 4 ? 80 : 100}%` }} /></div></div><div><div className="flex justify-between text-sm font-black text-[#0F172A]"><span>🔴 {tr("Red", "سرخ", "أحمر")}</span><span>75 ❤️</span></div><div className="hp-bar mt-1"><div className="hp-fill" style={{ width: `${movieStep >= 4 ? 75 : 100}%` }} /></div></div></div><div className="relative flex items-end justify-between px-2 pt-2"><div className="text-center"><div className="cartoon-kid bouncing" style={{ width: 130 }}><div className="ck-head">😤</div><div className="ck-body">🥋<span className="ck-belt" style={{ background: "#2563EB" }} /></div><div className="ck-legs"><span className="ck-leg" /><span className="ck-leg" /></div></div><div className="font-black text-[#0F172A]">🔵 BLUE</div></div><div className="text-center"><div className="text-4xl">🧑‍⚖️</div><div className="text-xs font-black text-[#0F172A]">{tr("Referee", "ریفری", "الحكم")}</div></div><div className="text-center"><div className="cartoon-kid bouncing" style={{ width: 130 }}><div className="ck-head">😡</div><div className="ck-body">🥋<span className="ck-belt" style={{ background: "#DC2626" }} /></div><div className="ck-legs"><span className="ck-leg" /><span className="ck-leg" /></div></div><div className="font-black text-[#0F172A]">🔴 RED</div></div></div>{moviePlaying && <div className="movie-trail on" style={{ left: "38%", bottom: 70 }} />}{(movieStep === 4 || movieStep === 6) && <div className="mt-2 text-center"><span className="point-pop">⭐ POINT! ⭐</span></div>}{moviePlaying && <div className="mt-1 text-center"><span className="burst" style={{ left: "46%" }}>💥⭐</span></div>}</div>}
