              {movieIdx === 3 && <div className="relative mt-2 flex items-end justify-center gap-6"><div className="text-center"><div className="cartoon-kid bouncing"><div className="ck-head">😊</div><div className="ck-body">🦸<span className="ck-belt" style={{ background: "#FDE047" }} /></div><div className="ck-legs"><span className="ck-leg" /><span className="ck-leg" /></div></div><div className="font-black text-[#0F172A]">{tr("Hero", "ہیرو", "البطل")}</div></div><div className="text-6xl pb-8">{currentMovie.steps[movieStep].actor}</div><div className="pb-8 text-5xl">🤝</div></div>}
